PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, display_name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('CUSTOMER','AGENT','MANAGER')));
CREATE TABLE IF NOT EXISTS sla_policies(id TEXT PRIMARY KEY, first_response_seconds INTEGER NOT NULL CHECK(first_response_seconds>0), resolution_seconds INTEGER NOT NULL CHECK(resolution_seconds>0));
CREATE TABLE IF NOT EXISTS tickets(id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id INTEGER NOT NULL REFERENCES users(id), policy_id TEXT NOT NULL REFERENCES sla_policies(id), priority TEXT NOT NULL CHECK(priority IN ('HIGH','NORMAL')), title TEXT NOT NULL, description TEXT NOT NULL, created_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('NEW','IN_PROGRESS','WAITING_FOR_CUSTOMER','RESOLVED','CLOSED')), assignee_id INTEGER REFERENCES users(id), assigned_at TEXT, closed_at TEXT, rejection_count INTEGER NOT NULL DEFAULT 0 CHECK(rejection_count>=0));
CREATE TABLE IF NOT EXISTS ticket_events(event_id INTEGER PRIMARY KEY AUTOINCREMENT, ticket_id INTEGER NOT NULL REFERENCES tickets(id), actor_id INTEGER REFERENCES users(id), occurred_at TEXT NOT NULL, occurred_at_raw TEXT NOT NULL, event_type TEXT NOT NULL, state_before TEXT, state_after TEXT NOT NULL, policy_id TEXT NOT NULL REFERENCES sla_policies(id), payload TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_events_ticket_order ON ticket_events(ticket_id,occurred_at,event_id);
CREATE TRIGGER IF NOT EXISTS immutable_event_update BEFORE UPDATE ON ticket_events BEGIN SELECT RAISE(ABORT,'ticket_events append only'); END;
CREATE TRIGGER IF NOT EXISTS immutable_event_delete BEFORE DELETE ON ticket_events BEGIN SELECT RAISE(ABORT,'ticket_events append only'); END;
CREATE TRIGGER IF NOT EXISTS immutable_policy_update BEFORE UPDATE ON sla_policies BEGIN SELECT RAISE(ABORT,'policy immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_policy_delete BEFORE DELETE ON sla_policies BEGIN SELECT RAISE(ABORT,'policy immutable'); END;
CREATE TABLE IF NOT EXISTS messages(source_event_id INTEGER PRIMARY KEY REFERENCES ticket_events(event_id), ticket_id INTEGER NOT NULL REFERENCES tickets(id), actor_id INTEGER REFERENCES users(id), created_at TEXT NOT NULL, visibility TEXT NOT NULL CHECK(visibility IN ('PUBLIC','INTERNAL')), content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sla_intervals(ticket_id INTEGER NOT NULL REFERENCES tickets(id), clock_type TEXT NOT NULL CHECK(clock_type IN ('first_response','resolution')), ordinal INTEGER NOT NULL, started_at TEXT NOT NULL, ended_at TEXT, business_seconds INTEGER, start_event_id INTEGER NOT NULL REFERENCES ticket_events(event_id), end_event_id INTEGER REFERENCES ticket_events(event_id), PRIMARY KEY(ticket_id,clock_type,ordinal), CHECK((ended_at IS NULL AND business_seconds IS NULL AND end_event_id IS NULL) OR (ended_at IS NOT NULL AND business_seconds>=0 AND end_event_id IS NOT NULL)));
CREATE TABLE IF NOT EXISTS ticket_sla(ticket_id INTEGER NOT NULL REFERENCES tickets(id), clock_type TEXT NOT NULL, closed_consumed_seconds INTEGER NOT NULL, applicable_deadline TEXT, state_at_event TEXT NOT NULL CHECK(state_at_event IN ('pending','met','breached')), remaining_at_event_seconds INTEGER NOT NULL CHECK(remaining_at_event_seconds>=0), PRIMARY KEY(ticket_id,clock_type));
CREATE TABLE IF NOT EXISTS assignment_snapshots(ticket_id INTEGER PRIMARY KEY REFERENCES tickets(id), assignment_event_id INTEGER NOT NULL REFERENCES ticket_events(event_id), assigned_at TEXT NOT NULL, first_response_sla_status_at_assignment TEXT NOT NULL CHECK(first_response_sla_status_at_assignment IN ('pending','breached')), resolution_sla_status_at_assignment TEXT NOT NULL CHECK(resolution_sla_status_at_assignment IN ('pending','breached')));
CREATE TABLE IF NOT EXISTS ticket_reviews(ticket_id INTEGER NOT NULL REFERENCES tickets(id), review_key TEXT NOT NULL, resolution_cycle_id INTEGER NOT NULL REFERENCES ticket_events(event_id), requested_event_id INTEGER NOT NULL REFERENCES ticket_events(event_id), completed_event_id INTEGER REFERENCES ticket_events(event_id), review_requested_at TEXT NOT NULL, review_completed_at TEXT, reviewed_by INTEGER REFERENCES users(id), handling_plan TEXT, PRIMARY KEY(ticket_id,review_key), UNIQUE(ticket_id,resolution_cycle_id));
CREATE UNIQUE INDEX IF NOT EXISTS one_open_review ON ticket_reviews(ticket_id) WHERE review_completed_at IS NULL;
